import sys

def solve(inp):
    tokens = inp.strip().split()
    if not tokens: return ''
    n = int(tokens[0])
    res = []
    c = 1
    for i in range(1, n + 1):
        res.append(''.join(str(c + j) for j in range(i)))
        c += i
    return '\n'.join(res)


def main():
    s = sys.stdin.read()
    if s.strip():
        print(solve(s))

if __name__ == '__main__':
    main()

